// 初始化认证状态
async function initAuth() {
  // 0. 优先检测系统授权激活状态
  try {
    const licRes = await fetch(`${getGatewayUrl()}/api/auth/license/status`).then(r => r.json());
    if (!licRes.activated) {
      switchAuthForm('license');
      const midRes = await fetch(`${getGatewayUrl()}/api/auth/machine-id`).then(r => r.json());
      document.getElementById('license-machine-id').value = midRes.machine_id;
      document.getElementById('auth-screen').classList.remove('hidden');
      return;
    }
  } catch (err) {
    console.warn('[License Engine] Verify license failed, connection error. Retrying...');
  }

  // 1. 检查系统是否已初始化
  const initRes = await fetch(`${getGatewayUrl()}/api/auth/check-init`).then(r => r.json()).catch(() => ({ initialized: true }));

  // 2. 如果已有 Token，先验证
  if (_authToken) {
    try {
      const me = await fetch(`${getGatewayUrl()}/api/auth/me`).then(r => r.json());
      if (me.success) {
        _currentUser = me.user;
        enterApp();
        return;
      }
    } catch (_) {}
    // Token 失效，清除
    localStorage.removeItem('kunlun_token');
    _authToken = '';
  }

  // 3. 无有效 Token，显示登录界面
  if (!initRes.initialized) {
    // 首次启动：直接显示注册界面
    switchAuthForm('register');
    document.getElementById('reg-subtitle').textContent = '首次使用，请创建您的超级管理员账号';
    document.getElementById('invite-code-group').style.display = 'none';
  } else {
    switchAuthForm('login');
  }
  document.getElementById('auth-screen').classList.remove('hidden');
}

function switchAuthForm(type) {
  document.getElementById('form-login').style.display = type === 'login' ? 'block' : 'none';
  document.getElementById('form-register').style.display = type === 'register' ? 'block' : 'none';
  document.getElementById('form-license').style.display = type === 'license' ? 'block' : 'none';
  // 清空错误信息
  ['login-err','login-ok','reg-err','reg-ok','license-err','license-ok'].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.className = el.className.replace(' show', '');
      el.textContent = '';
    }
  });
}

function copyMachineId() {
  const input = document.getElementById('license-machine-id');
  input.select();
  document.execCommand('copy');
  alert('📋 机器特征码已成功复制到剪贴板！');
}

async function doActivateLicense() {
  const key = document.getElementById('license-key').value.trim();
  const errEl = document.getElementById('license-err');
  const okEl = document.getElementById('license-ok');
  const btn = document.getElementById('license-btn');

  if (!key) {
    errEl.textContent = '请输入激活码。';
    errEl.classList.add('show');
    return;
  }

  btn.disabled = true;
  btn.textContent = '正在激活...';
  errEl.classList.remove('show');
  okEl.classList.remove('show');

  try {
    const res = await fetch(`${getGatewayUrl()}/api/auth/license/activate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ license_key: key })
    }).then(r => r.json());

    if (res.success) {
      okEl.textContent = '🎉 激活成功！正在进入系统...';
      okEl.classList.add('show');
      setTimeout(() => {
        // 重新运行初始化以进入登录/注册界面
        initAuth();
      }, 1500);
    } else {
      errEl.textContent = res.error || '激活失败，请核对激活码。';
      errEl.classList.add('show');
      btn.disabled = false;
      btn.textContent = '激活系统';
    }
  } catch (err) {
    errEl.textContent = '网络连接失败，请确保本地网关已启动。';
    errEl.classList.add('show');
    btn.disabled = false;
    btn.textContent = '激活系统';
  }
}

